import {escapeHTML as h, safeURL} from './core.js';
import {RESEARCH_DOMAINS, RESEARCH_KINDS, RELEASE_LABELS, LEARNING_PATHS, TECHNIQUE_LIBRARY, TECHNIQUE_LEVELS, normalizeResearchPreferences, filterResearchItems, filterTechniques, isResearchEvent} from './research-core.js';

const STORAGE_KEY='cyberwatch.research.v1';
const labelDate=value=>value?new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Dhaka'}).format(new Date(value)):'Not recorded';
const link=(label,url)=>`<a href="${h(safeURL(url))}" target="_blank" rel="noopener noreferrer">${h(label)} <span aria-hidden="true">↗</span></a>`;
const domainTags=domains=>(domains||[]).map(domain=>`<span>${h(RESEARCH_DOMAINS[domain]||domain)}</span>`).join('');
const options=(labels,current)=>Object.entries(labels).map(([value,label])=>`<option value="${h(value)}"${value===current?' selected':''}>${h(label)}</option>`).join('');

/** A browser-local study workspace over the same collected, validated snapshot. */
export function createResearchLab({getData,getSaved,onSave,onOpen,onToast,onChange,onResults}) {
  let preferences=normalizeResearchPreferences({}),storageAvailable=true,mounted=false;
  try {const stored=localStorage.getItem(STORAGE_KEY);if(stored&&stored.length<200000)preferences=normalizeResearchPreferences(JSON.parse(stored));}catch{storageAvailable=false;}
  const filters={query:'',domain:'all',kind:'all',perspective:'all',status:'all',source:'all',period:'all'};
  const techniqueFilters={query:'',level:'all',status:'all'};
  let tab='watch',limit=12,watchMode='all';
  const root=()=>document.querySelector('#research-view');
  const sources=()=>getData()?.sources.filter(source=>source.group==='research')||[];
  const records=()=>getData()?.events.filter(isResearchEvent)||[];
  function filteredEvents(){return filterResearchItems(records(),{...filters,reviewed:preferences.reviewed,followed:preferences.followed,savedIds:getSaved()});}
  function persist(message='') {
    preferences=normalizeResearchPreferences(preferences);
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(preferences));storageAvailable=true;}catch{storageAvailable=false;}
    root()?.querySelectorAll('.research-local-note').forEach(notice=>{notice.textContent=storageAvailable?'Progress saved in this browser':'Storage unavailable · session-only progress';});
    if(message)onToast(storageAvailable?message:'Updated for this session. Browser storage is unavailable.');
  }
  function toggleList(name,id) {const values=new Set(preferences[name]);if(values.has(id))values.delete(id);else values.add(id);preferences[name]=[...values];}
  function mount() {
    const container=root();if(!container||mounted)return;
    container.innerHTML=`<div class="research-shell">
      <section class="research-hero"><div><span class="eyebrow">RESEARCH / PRACTICE / PROGRESS</span><h2>Stay curious. Build capability.</h2><p>Follow official standards, study original research, and turn what you learn into stronger offensive and defensive practice.</p><div class="research-summary" id="research-summary"></div></div><div class="research-hero-mark" aria-hidden="true"><span>LEARN</span><i></i><span>VALIDATE</span></div></section>
      <div class="research-tabs" role="tablist" aria-label="Research Lab sections"><button id="research-tab-watch" class="research-tab" data-research-tab="watch" role="tab" aria-controls="research-panel-watch">Standards watch</button><button id="research-tab-feed" class="research-tab" data-research-tab="feed" role="tab" aria-controls="research-panel-feed">Research feed</button><button id="research-tab-paths" class="research-tab" data-research-tab="paths" role="tab" aria-controls="research-panel-paths">Learning paths</button><button id="research-tab-techniques" class="research-tab" data-research-tab="techniques" role="tab" aria-controls="research-panel-techniques">Techniques library</button></div>
      <div class="research-domain-bar" aria-label="Filter by security domain">${optionsToButtons()}</div>
      <section id="research-panel-watch" role="tabpanel" aria-labelledby="research-tab-watch" tabindex="0"><div class="research-section-heading"><div><span class="eyebrow">OFFICIAL PROJECTS</span><h3>Your standards watch.</h3><p>Published editions and repository releases, with source dates and collection status.</p></div><label class="research-select">Show<select id="research-watch-mode" aria-label="Filter standards watch"><option value="all">All tracked projects</option><option value="following">Following</option><option value="changed">Changed in last 30 days</option><option value="errors">Needs attention</option></select></label></div><div class="research-watch-grid" id="research-watch-grid"></div><p class="research-footnote">Edition watches track the official project page; repository releases may describe tooling or project updates. First observation establishes a baseline. A detected change is labelled separately from its publication date.</p></section>
      <section id="research-panel-feed" role="tabpanel" aria-labelledby="research-tab-feed" tabindex="0" hidden><div class="research-toolbar"><label class="research-search"><span>Search research</span><input id="research-search" type="search" placeholder="Search techniques, projects, CVEs…" autocomplete="off"></label><label class="research-select">Publication<select id="research-kind" aria-label="Filter research type">${options({all:'All publications',...RESEARCH_KINDS},'all')}</select></label><label class="research-select">Perspective<select id="research-perspective" aria-label="Filter research perspective">${options({all:'Both perspectives',offensive:'Offensive',defensive:'Defensive'},'all')}</select></label><label class="research-select">Reading list<select id="research-status" aria-label="Filter reading status">${options({all:'All items',unread:'Not reviewed',reviewed:'Reviewed',saved:'Saved',following:'Following'},'all')}</select></label><label class="research-select">Date<select id="research-period" aria-label="Filter research dates">${options({all:'All dates','7d':'Last 7 days','30d':'Last 30 days','90d':'Last 90 days'},'all')}</select></label><label class="research-select">Source<select id="research-source" aria-label="Filter research source"></select></label><button class="button secondary research-reset" data-research-reset>Reset filters</button></div><div class="research-results" id="research-results" role="status" aria-live="polite"></div><div class="research-grid" id="research-grid"></div><button class="button secondary research-load-more" data-research-more hidden>Load more research</button><p class="research-footnote">Topics and perspectives are navigation tags. A publication can discuss an established technique; inclusion does not claim the method is newly discovered. Open the original source for its complete context.</p></section>
      <section id="research-panel-paths" role="tabpanel" aria-labelledby="research-tab-paths" tabindex="0" hidden><div class="research-section-heading"><div><span class="eyebrow">READ → PRACTICE → VERIFY</span><h3>Give your learning a direction.</h3><p>Six editorial study plans pair controlled lab practice with defensive validation. Use the checklists to track your own work.</p></div><span class="research-local-note" aria-live="polite">${storageAvailable?'Progress saved in this browser':'Storage unavailable · session-only progress'}</span></div><div class="research-path-grid" id="research-path-grid"></div><p class="research-footnote">These study plans link to independent learning resources. Progress is self-reported and stays in this browser; it is not a certification or an assessment of proficiency.</p></section>
      <section id="research-panel-techniques" role="tabpanel" aria-labelledby="research-tab-techniques" tabindex="0" hidden><div class="research-section-heading"><div><span class="eyebrow">METHOD / EVIDENCE / DEFENSE</span><h3>Turn reading into practical skill.</h3><p>24 original study exercises pair a controlled lab method with a defensive check and a common testing mistake. Start with the linked primary guidance, then record your own evidence.</p></div><span class="research-local-note" aria-live="polite">${storageAvailable?'Progress saved in this browser':'Storage unavailable · session-only progress'}</span></div><div class="research-toolbar research-technique-toolbar"><label class="research-search"><span>Search techniques</span><input id="technique-search" type="search" placeholder="Try OAuth, mobile, concurrency, agent tools…" autocomplete="off"></label><label class="research-select">Experience<select id="technique-level" aria-label="Filter technique experience">${options({all:'All levels',...TECHNIQUE_LEVELS},'all')}</select></label><label class="research-select">Study list<select id="technique-status" aria-label="Filter technique study status">${options({all:'All techniques',unread:'To study',reviewed:'Reviewed'},'all')}</select></label><button class="button secondary" data-technique-reset>Reset techniques</button></div><div class="research-results" id="technique-results" role="status" aria-live="polite"></div><div class="research-technique-grid" id="research-technique-grid"></div><p class="research-footnote">Practice uses authorized training apps, synthetic data and isolated labs. Times are editorial study estimates. “Reviewed” records your reading, not demonstrated proficiency. The reviewed date belongs to this study card; source-dated new publications appear in the Research feed.</p><button class="button secondary" data-technique-latest>Explore recent research publications <span aria-hidden="true">↗</span></button></section>
    </div>`;
    container.addEventListener('click',handleClick);container.addEventListener('input',handleInput);container.addEventListener('change',handleChange);container.addEventListener('keydown',handleKeys);mounted=true;
  }
  function optionsToButtons(){return Object.entries({all:'All domains',...RESEARCH_DOMAINS}).map(([value,label])=>`<button data-research-domain="${h(value)}" aria-pressed="${filters.domain===value}">${h(label)}</button>`).join('');}
  function followButton(sourceId){const following=preferences.followed.includes(sourceId);return `<button class="research-follow" data-research-follow="${h(sourceId)}" aria-pressed="${following}">${following?'Following':'Follow source'}</button>`;}
  function renderWatch() {
    const items=(getData()?.researchWatch||[]).filter(item=>(filters.domain==='all'||item.domains.includes(filters.domain))&&(watchMode!=='following'||preferences.followed.includes(item.sourceId))&&(watchMode!=='changed'||Boolean(item.changedAt&&Date.parse(item.changedAt)>=Date.now()-2592000000))&&(watchMode!=='errors'||item.status==='error'));
    root().querySelector('#research-watch-grid').innerHTML=items.length?items.map(item=>{
      const type=item.watchType==='release'?'Repository release':'Edition watch';
      const status=item.status==='error'?'Check failed':item.changeDetected?'Change observed':'Checked';
      const dateLabel=item.dateBasis==='source-updated'?'Source updated':'Published';
      return `<article class="research-watch-card${item.status==='error'?' research-error':''}" data-watch-source="${h(item.sourceId)}"><div class="research-card-top"><span class="research-kind">${h(type)}</span><span class="research-status ${item.status==='error'?'is-error':item.changeDetected?'is-new':''}">${h(status)}</span></div><h3>${h(item.name)}</h3><div class="research-version">${h(item.currentLabel)}</div><div class="research-tags">${domainTags(item.domains)}${item.watchType==='release'?`<span>${h(RELEASE_LABELS[item.releaseStatus])}</span>`:''}</div><dl class="research-meta"><div><dt>${item.publishedAt?h(dateLabel):'Tracking since'}</dt><dd>${h(labelDate(item.publishedAt||item.firstObservedAt))}</dd></div><div><dt>Last successful check</dt><dd>${h(labelDate(item.lastSuccessAt))}</dd></div></dl>${item.changedAt?`<p class="research-change-note">The last change was observed on ${h(labelDate(item.changedAt))}. Review the official source for what changed.</p>`:''}${item.status==='error'?`<p class="research-change-note">${h(item.error||'The latest check failed. Last available details are retained.')}</p>`:''}<div class="research-card-actions">${link('Open official source',item.referenceUrl)}${followButton(item.sourceId)}</div></article>`;
    }).join(''):empty('No projects match this view.',getData()?.researchWatch?.length?'Try another domain or select all tracked projects.':'A publisher refresh will populate the official standards watches. You can explore the learning paths now.');
  }
  function renderFeed() {
    const items=filteredEvents();const channelMap=new Map(sources().map(source=>[source.id,source]));
    if(onResults)onResults(tab==='feed'?items.length:0);
    const sourceSelect=root().querySelector('#research-source');
    const sourceOptions={all:'All research sources',...Object.fromEntries(sources().filter(source=>records().some(event=>event.sourceId===source.id)).map(source=>[source.id,source.name]))};
    if(filters.source!=='all'&&!Object.hasOwn(sourceOptions,filters.source)){const source=sources().find(item=>item.id===filters.source);sourceOptions[filters.source]=source?.name||'Selected source';}
    sourceSelect.innerHTML=options(sourceOptions,filters.source);
    root().querySelector('#research-results').textContent=`${items.length} publication${items.length===1?'':'s'} · ${items.filter(event=>!preferences.reviewed.includes(event.id)).length} not reviewed`;
    root().querySelector('#research-grid').innerHTML=items.length?items.slice(0,limit).map(event=>{
      const learning=event.learning,reviewed=preferences.reviewed.includes(event.id),saved=getSaved().has(event.id),channel=channelMap.get(event.sourceId);
      const release=['release','tool'].includes(learning.kind)?`<span>${h(RELEASE_LABELS[learning.releaseStatus])}</span>`:'';
      return `<article class="research-card${reviewed?' research-reviewed':''}"><div class="research-card-top"><span class="research-kind">${h(RESEARCH_KINDS[learning.kind]||'Project update')}</span><span class="research-status">${reviewed?'Reviewed':'Not reviewed'}</span></div><div class="research-publication"><span>${h(channel?.name||event.organization)}</span><time datetime="${h(event.publishedAt)}" title="${h(learning.dateBasis==='source-updated'?'Source update date':'Publisher publication date')}">${learning.dateBasis==='source-updated'?'Updated ':''}${h(labelDate(event.publishedAt))}</time></div><h3><button data-research-open="${h(event.id)}">${h(event.title)}</button></h3><p class="research-card-summary">${h(event.summary)}</p><div class="research-tags">${domainTags(learning.domains)}${learning.perspectives.map(lens=>`<span class="research-lens-tag ${h(lens)}">${h(lens==='offensive'?'Offensive':'Defensive')}</span>`).join('')}${release}</div>${channel?.status==='error'?'<p class="research-change-note">Latest source check failed · retained publication</p>':''}<div class="research-card-actions"><button class="research-read" data-research-open="${h(event.id)}">Read publication <span aria-hidden="true">↗</span></button><button data-research-reviewed="${h(event.id)}" aria-pressed="${reviewed}">${reviewed?'Reviewed ✓':'Mark reviewed'}</button><button data-research-save="${h(event.id)}" aria-pressed="${saved}" aria-label="${saved?'Remove from':'Save to'} watchlist: ${h(event.title)}">${saved?'Saved ✓':'Save'}</button></div><div class="research-source-follow">${followButton(event.sourceId)}</div></article>`;
    }).join(''):empty('No research matches these filters.',records().length?'Clear a filter or broaden your reading list.':'The next publisher refresh will collect research from the configured sources. Standards watches and learning paths remain available.');
    root().querySelector('[data-research-more]').hidden=items.length<=limit;
  }
  function renderPaths() {
    const paths=LEARNING_PATHS.filter(path=>filters.domain==='all'||path.domain===filters.domain||filters.domain==='api'&&path.id==='web-api'||filters.domain==='identity'&&path.id==='cloud-identity');
    root().querySelector('#research-path-grid').innerHTML=paths.length?paths.map(path=>{
      const progress=new Set(preferences.progress[path.id]||[]),complete=path.steps.filter(([id])=>progress.has(id)).length;
      return `<article class="research-path-card"><div class="research-path-top"><span class="research-kind">${h(RESEARCH_DOMAINS[path.domain])}</span><span class="research-level">${h(path.level)}</span></div><h3>${h(path.title)}</h3><p>${h(path.summary)}</p><div class="research-progress-label"><span>${complete} of ${path.steps.length} steps completed</span><strong>${Math.round(complete/path.steps.length*100)}%</strong></div><progress class="research-progress" value="${complete}" max="${path.steps.length}" aria-label="${h(path.title)} progress"></progress><div class="research-lenses"><div class="research-lens offensive"><strong>Offensive practice</strong><p>${h(path.offensive)}</p></div><div class="research-lens defensive"><strong>Defensive validation</strong><p>${h(path.defensive)}</p></div></div><div class="research-path-steps">${path.steps.map(([id,label])=>`<label><input type="checkbox" data-research-step="${h(id)}" data-research-path="${h(path.id)}"${progress.has(id)?' checked':''}><span>${h(label)}</span></label>`).join('')}</div><div class="research-path-links">${path.links.map(([label,url])=>link(label,url)).join('')}</div><details class="research-notes"><summary>Personal study notes</summary><label for="notes-${h(path.id)}">Evidence, observations and next steps</label><textarea id="notes-${h(path.id)}" data-research-notes="${h(path.id)}" maxlength="4000" rows="4" placeholder="Write your observations here…">${h(preferences.notes[path.id]||'')}</textarea><small>${storageAvailable?'Saved on this browser as you type. Maximum 4,000 characters.':'Storage unavailable; notes last for this session only.'}</small></details></article>`;
    }).join(''):empty('Choose another learning domain.','The six learning paths cover web/API, mobile, AI, cloud/identity, detection and secure engineering.');
  }
  function renderTechniques() {
    const container=root(),items=filterTechniques(TECHNIQUE_LIBRARY,{...techniqueFilters,domain:filters.domain,reviewed:preferences.techniqueReviewed});
    const openIds=new Set([...container.querySelectorAll('.research-technique-details[open]')].map(item=>item.dataset.techniqueDetails));
    container.querySelector('#technique-results').textContent=`${items.length} technique${items.length===1?'':'s'} · ${items.filter(item=>preferences.techniqueReviewed.includes(item.id)).length} reviewed · filter by domain above`;
    container.querySelector('#research-technique-grid').innerHTML=items.length?items.map(item=>{
      const reviewed=preferences.techniqueReviewed.includes(item.id);
      return `<article class="research-technique-card${reviewed?' research-reviewed':''}"><div class="research-card-top"><span class="research-kind">${h(TECHNIQUE_LEVELS[item.level])}</span><span class="research-status">${reviewed?'Reviewed':'To study'}</span></div><div class="research-technique-heading"><h3>${h(item.title)}</h3><p class="research-technique-summary">${h(item.objective)}</p></div><div class="research-tags">${domainTags(item.domains)}<span>${item.minutes} min study estimate</span></div><details class="research-technique-details" data-technique-details="${h(item.id)}"${openIds.has(item.id)?' open':''}><summary>Open practice method</summary><h4>Lab method</h4><ol class="research-technique-method">${item.method.map(step=>`<li>${h(step)}</li>`).join('')}</ol><div class="research-technique-validation"><strong>Defensive validation</strong><p>${h(item.defensive)}</p></div><p class="research-technique-pitfall"><strong>Common mistake</strong> ${h(item.pitfall)}</p><div class="research-technique-sources"><strong>Primary guidance & labs</strong>${item.links.map(([label,url])=>link(label,url)).join('')}</div><p class="research-technique-meta">Study card reviewed ${h(labelDate(item.reviewedAt))} · editorial exercise</p></details><div class="research-card-actions"><button data-technique-reviewed="${h(item.id)}" aria-pressed="${reviewed}" aria-label="${reviewed?'Mark as to study':'Mark reviewed'}: ${h(item.title)}">${reviewed?'Reviewed ✓':'Mark reviewed'}</button><span class="research-technique-meta">Practice → collect evidence → retest</span></div></article>`;
    }).join(''):empty('No techniques match this view.','Try another domain, experience level or search term.');
  }
  function empty(title,body){return `<div class="research-empty"><span aria-hidden="true">◇</span><h3>${h(title)}</h3><p>${h(body)}</p></div>`;}
  function render() {
    mount();const container=root();if(!container)return;
    container.querySelectorAll('[data-research-tab]').forEach(button=>{const active=button.dataset.researchTab===tab;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;button.classList.toggle('active',active);});
    for(const name of ['watch','feed','paths','techniques'])container.querySelector(`#research-panel-${name}`).hidden=tab!==name;
    container.querySelectorAll('[data-research-domain]').forEach(button=>{const active=button.dataset.researchDomain===filters.domain;button.setAttribute('aria-pressed',String(active));button.classList.toggle('active',active);});
    container.querySelector('#research-summary').innerHTML=`<span><strong>${records().length}</strong> publications</span><span><strong>${getData()?.researchWatch?.length||0}</strong> project watches</span><span><strong>${LEARNING_PATHS.length}</strong> learning paths</span><span><strong>${TECHNIQUE_LIBRARY.length}</strong> practice techniques</span>`;
    renderWatch();renderFeed();
    if(tab==='paths'&&!container.querySelector('textarea:focus'))renderPaths();
    if(tab==='techniques')renderTechniques();
  }
  function syncInputs() {
    const container=root();if(!container||!mounted)return;
    container.querySelector('#research-search').value=filters.query;
    for(const key of ['kind','perspective','status','period','source']){const element=container.querySelector(`#research-${key}`);if(element)element.value=filters[key];}
  }
  function handleClick(event) {
    const button=event.target.closest('button');if(!button)return;
    if(button.dataset.researchTab){tab=button.dataset.researchTab;render();return;}
    if(button.dataset.researchDomain){filters.domain=button.dataset.researchDomain;limit=12;render();return;}
    if(button.dataset.researchOpen){onOpen(button.dataset.researchOpen);return;}
    if(button.dataset.researchSave){onSave(button.dataset.researchSave);return;}
    if(button.dataset.researchReviewed){toggleList('reviewed',button.dataset.researchReviewed);persist(preferences.reviewed.includes(button.dataset.researchReviewed)?'Marked as reviewed.':'Marked as not reviewed.');renderFeed();onChange();return;}
    if(button.dataset.researchFollow){toggleList('followed',button.dataset.researchFollow);persist(preferences.followed.includes(button.dataset.researchFollow)?'Following this source in Research Lab.':'Source removed from your following list.');renderWatch();renderFeed();return;}
    if(button.dataset.techniqueReviewed){const id=button.dataset.techniqueReviewed;toggleList('techniqueReviewed',id);persist(preferences.techniqueReviewed.includes(id)?'Technique marked as reviewed.':'Technique moved back to your study list.');renderTechniques();onChange();const target=[...root().querySelectorAll('[data-technique-reviewed]')].find(item=>item.dataset.techniqueReviewed===id);target?.focus({preventScroll:true});return;}
    if(button.hasAttribute('data-technique-reset')){Object.assign(techniqueFilters,{query:'',level:'all',status:'all'});filters.domain='all';root().querySelector('#technique-search').value='';root().querySelector('#technique-level').value='all';root().querySelector('#technique-status').value='all';render();return;}
    if(button.hasAttribute('data-technique-latest')){tab='feed';filters.period='30d';filters.kind='all';filters.status='all';filters.source='all';filters.query='';filters.perspective='all';limit=12;render();syncInputs();root().querySelector('#research-search').focus();return;}
    if(button.hasAttribute('data-research-more')){const old=limit;limit+=12;renderFeed();root().querySelectorAll('.research-card h3 button')[old]?.focus();return;}
    if(button.hasAttribute('data-research-reset')){reset();render();onToast('Research filters cleared.');}
  }
  function handleInput(event) {
    if(event.target.id==='research-search'){filters.query=event.target.value.slice(0,300);limit=12;renderFeed();}
    if(event.target.id==='technique-search'){techniqueFilters.query=event.target.value.slice(0,300);renderTechniques();}
    if(event.target.dataset.researchNotes){preferences.notes[event.target.dataset.researchNotes]=event.target.value.slice(0,4000);persist();const note=event.target.parentElement.querySelector('small');note.textContent=storageAvailable?'Saved on this browser. Maximum 4,000 characters.':'Browser storage unavailable; notes last for this session only.';}
  }
  function handleChange(event) {
    if(event.target.id==='research-watch-mode'){watchMode=event.target.value;renderWatch();return;}
    for(const key of ['level','status'])if(event.target.id===`technique-${key}`){techniqueFilters[key]=event.target.value;renderTechniques();return;}
    for(const key of ['kind','perspective','status','period','source'])if(event.target.id===`research-${key}`){filters[key]=event.target.value;limit=12;renderFeed();return;}
    if(event.target.dataset.researchStep){const path=event.target.dataset.researchPath,step=event.target.dataset.researchStep;const selected=new Set(preferences.progress[path]||[]);if(event.target.checked)selected.add(step);else selected.delete(step);preferences.progress[path]=[...selected];persist();const card=event.target.closest('.research-path-card');const total=LEARNING_PATHS.find(item=>item.id===path)?.steps.length||4;card.querySelector('progress').value=selected.size;card.querySelector('.research-progress-label').innerHTML=`<span>${selected.size} of ${total} steps completed</span><strong>${Math.round(selected.size/total*100)}%</strong>`;onChange();}
  }
  function handleKeys(event){if(!event.target.matches('[data-research-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...root().querySelectorAll('[data-research-tab]')],index=tabs.indexOf(event.target),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tab=tabs[next].dataset.researchTab;render();tabs[next].focus();}
  function reset(){Object.assign(filters,{query:'',domain:'all',kind:'all',perspective:'all',status:'all',source:'all',period:'all'});Object.assign(techniqueFilters,{query:'',level:'all',status:'all'});limit=12;watchMode='all';syncInputs();if(mounted){root().querySelector('#research-watch-mode').value='all';root().querySelector('#technique-search').value='';root().querySelector('#technique-level').value='all';root().querySelector('#technique-status').value='all';}}
  function setSource(id){
    const watched=(getData()?.researchWatch||[]).some(item=>item.sourceId===id);
    if(watched&&!records().some(event=>event.sourceId===id)){
      tab='watch';filters.domain='all';watchMode='all';render();root().querySelector('#research-watch-mode').value='all';
      const card=[...root().querySelectorAll('[data-watch-source]')].find(item=>item.dataset.watchSource===id);card?.scrollIntoView({block:'center'});card?.querySelector('a')?.focus({preventScroll:true});return;
    }
    filters.source=id;tab='feed';render();syncInputs();
  }
  function focusSearch(){if(tab==='techniques'){root()?.querySelector('#technique-search')?.focus();return;}tab='feed';render();root()?.querySelector('#research-search')?.focus();}
  window.addEventListener('storage',event=>{if(event.key!==STORAGE_KEY)return;try{if((event.newValue||'').length>200000)return;preferences=normalizeResearchPreferences(JSON.parse(event.newValue||'{}'));if(mounted&&!root().hidden)render();onChange();}catch{/* Preserve current state on malformed cross-tab data. */}});
  return {render,filteredEvents,reset,setSource,focusSearch,reviewedCount:()=>records().filter(event=>preferences.reviewed.includes(event.id)).length,progressCount:()=>LEARNING_PATHS.reduce((total,path)=>total+path.steps.filter(([id])=>(preferences.progress[path.id]||[]).includes(id)).length,0)};
}
